def main() -> int:
    started = dt.datetime.now(dt.timezone.utc).isoformat()
    cp = subprocess.run(ARGV, input=REMOTE, text=True, capture_output=True, timeout=180)
    STDERR.write_text(cp.stderr, encoding="utf-8")
    invocation = {
        "started_at_utc": started,
        "cwd": str(Path.cwd()),
        "argv": ARGV,
        "timeout_seconds": 180,
        "remote_program_sha256": hashlib.sha256(REMOTE.encode()).hexdigest(),
        "local_exit_status": cp.returncode,
    }
    if cp.stdout.strip():
        try:
            obj = json.loads(cp.stdout)
            invocation["remote_exit_status"] = obj.get("remote_exit_status")
            OUT.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        except Exception as exc:
            invocation["stdout_parse_error"] = f"{type(exc).__name__}: {exc}"
            (OUT.with_suffix(".stdout.txt")).write_text(cp.stdout, encoding="utf-8")
    else:
        invocation["stdout_empty"] = True
    Path(__file__).with_name("invocation.json").write_text(
        json.dumps(invocation, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    print(json.dumps({"local_exit_status": cp.returncode,
                      "stdout_bytes": len(cp.stdout.encode()),
                      "stderr_path": str(STDERR),
                      "result_path": str(OUT),
                      "invocation_path": str(Path(__file__).with_name('invocation.json')),
                      "stdout_head": cp.stdout[:1200]}, ensure_ascii=False))
    return cp.returncode


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except subprocess.TimeoutExpired as exc:
        print(f"SSH collection timed out: {exc}", file=sys.stderr)
        raise SystemExit(124)

